namespace AI103.ChatApp.Domain.Entities;

/// <summary>
/// Who authored a message. Mirrors the roles used by OpenAI-style APIs.
/// </summary>
public enum ChatRole
{
    /// <summary>System-level instructions that shape model behaviour.</summary>
    System,

    /// <summary>A prompt written by the end user.</summary>
    User,

    /// <summary>A reply generated by the model.</summary>
    Assistant
}
